"""Publish the pricing simulation fix and quote-deletion readiness only; financial gates stay closed."""
import pathlib,json,importlib.util,hashlib,base64,datetime
R=pathlib.Path(__file__).resolve().parents[1];O=pathlib.Path('/private/tmp/finance67');sp=importlib.util.spec_from_file_location('c',R/'scripts/capture-financial-readers-63.py');m=importlib.util.module_from_spec(sp);sp.loader.exec_module(m)
def main():
 p=json.loads((O/'preparation.json').read_text());assert hashlib.sha256((R/'backend/staff-service/delivery-pricing.js').read_bytes()).hexdigest()==p['sourceSha256'];assert 'pass 187' in (O/'unit-tests.log').read_text() and 'fail 0' in (O/'unit-tests.log').read_text();assert 'pass 241' in (O/'deletion-tests.log').read_text() and 'fail 0' in (O/'deletion-tests.log').read_text();routing=json.loads((O/'routing-probe-result.json').read_text());assert all(x['result']['routingReady'] and x['temporaryFunctionDeleted'] for x in routing['probes']);s=m.session();lam=s.client('lambda');iam=s.client('iam');cf=s.client('cloudformation');bases={k:json.loads((O/(k+'.config.private.json')).read_text()) for k in ['staff','cleanup']}
 for k,base in bases.items():
  c=lam.get_function_configuration(FunctionName=base['FunctionName']);assert c['CodeSha256']==base['CodeSha256'] and c['RevisionId']==base['RevisionId'],'LIVE_DRIFT '+k
 state={'part':67,'environment':'Staging','activationPerformed':False,'financialActivationPerformed':False,'applicationWrites':False,'functions':[]};save=lambda:(O/'publication.json').write_text(json.dumps(state,indent=2))
 template=json.loads((R/'backend/customer-quote-cleanup-access.staging.json').read_text());doc=template['Resources']['CustomerQuoteCleanupAccess']['Properties']['PolicyDocument'];checks=[]
 for action,table,key,expected in [('dynamodb:Query','staging-DeliveryQuotes','CUSTOMER#readiness67','allowed'),('dynamodb:DeleteItem','staging-DeliveryQuotes','CUSTOMER#readiness67','allowed'),('dynamodb:Query','staging-DeliveryQuotes','BRANCH#readiness67','implicitDeny'),('dynamodb:Scan','staging-DeliveryQuotes','CUSTOMER#readiness67','implicitDeny'),('dynamodb:DeleteItem','staging-LedgerEntries','CUSTOMER#readiness67','implicitDeny')]:
  decision=iam.simulate_custom_policy(PolicyInputList=[json.dumps(doc)],ActionNames=[action],ResourceArns=['arn:aws:dynamodb:us-east-1:699561669180:table/'+table],ContextEntries=[{'ContextKeyName':'dynamodb:LeadingKeys','ContextKeyType':'stringList','ContextKeyValues':[key]}])['EvaluationResults'][0]['EvalDecision'];assert decision==expected;checks.append({'action':action,'table':table,'decision':decision})
 stack='staging-finance-quote-cleanup-access-67';change=cf.create_change_set(StackName=stack,ChangeSetName='quote-cleanup67',ChangeSetType='CREATE',TemplateBody=json.dumps(template),Capabilities=['CAPABILITY_NAMED_IAM']);cf.get_waiter('change_set_create_complete').wait(ChangeSetName=change['Id'],WaiterConfig={'Delay':2,'MaxAttempts':90});plan=cf.describe_change_set(ChangeSetName=change['Id']);assert len(plan['Changes'])==1 and plan['Changes'][0]['ResourceChange']['Action']=='Add';cf.execute_change_set(ChangeSetName=change['Id']);cf.get_waiter('stack_create_complete').wait(StackName=stack,WaiterConfig={'Delay':3,'MaxAttempts':90});state['accessStack']=stack;state['policySimulation']=checks;save();print(json.dumps({'cleanupAccessPrepared':True}),flush=True)
 effective=[]
 for action,table,key in [('dynamodb:Query','staging-DeliveryQuotes','CUSTOMER#readiness67'),('dynamodb:DeleteItem','staging-DeliveryQuotes','CUSTOMER#readiness67'),('dynamodb:ConditionCheckItem','staging-AccountDeletion','SUBJECT#CUSTOMER#readiness67'),('dynamodb:ConditionCheckItem','WizzUser_users_staging','readiness67')]:
  decision=iam.simulate_principal_policy(PolicySourceArn=bases['cleanup']['Role'],ActionNames=[action],ResourceArns=['arn:aws:dynamodb:us-east-1:699561669180:table/'+table],ContextEntries=[{'ContextKeyName':'dynamodb:LeadingKeys','ContextKeyType':'stringList','ContextKeyValues':[key]}])['EvaluationResults'][0]['EvalDecision'];effective.append({'action':action,'table':table,'decision':decision})
 state['effectiveCleanupIam']=effective;save();assert all(x['decision']=='allowed' for x in effective),'CLEANUP_GUARD_IAM_NOT_READY'
 data=(O/'staff.candidate.zip').read_bytes();assert base64.b64encode(hashlib.sha256(data).digest()).decode()==p['staffCandidateCodeSha256'];c=lam.get_function_configuration(FunctionName=bases['staff']['FunctionName']);assert c['RevisionId']==bases['staff']['RevisionId'];lam.update_function_code(FunctionName=c['FunctionName'],RevisionId=c['RevisionId'],ZipFile=data);lam.get_waiter('function_updated_v2').wait(FunctionName=c['FunctionName'],WaiterConfig={'Delay':2,'MaxAttempts':90});new=lam.get_function_configuration(FunctionName=c['FunctionName']);assert new['CodeSha256']==p['staffCandidateCodeSha256']
 for f in ['Environment','Role','Runtime','Handler','Layers','Timeout','MemorySize','Architectures','VpcConfig']:assert new.get(f)==bases['staff'].get(f)
 state['functions'].append({'name':new['FunctionName'],'codeSha256':new['CodeSha256'],'revisionId':new['RevisionId'],'configurationPreserved':True});save();print(json.dumps({'pricingSimulationFixPublished':True}),flush=True)
 old=bases['cleanup'];c=lam.get_function_configuration(FunctionName=old['FunctionName']);assert c['RevisionId']==old['RevisionId'] and c['CodeSha256']==old['CodeSha256'];env={**c.get('Environment',{}).get('Variables',{}),'DELIVERY_QUOTES_ENABLED':'true'};lam.update_function_configuration(FunctionName=c['FunctionName'],RevisionId=c['RevisionId'],Environment={'Variables':env});lam.get_waiter('function_updated_v2').wait(FunctionName=c['FunctionName'],WaiterConfig={'Delay':2,'MaxAttempts':90});new=lam.get_function_configuration(FunctionName=c['FunctionName']);assert new['CodeSha256']==old['CodeSha256'] and new['Environment']['Variables']==env
 for f in ['Role','Runtime','Handler','Layers','Timeout','MemorySize','Architectures','VpcConfig']:assert new.get(f)==old.get(f)
 state['functions'].append({'name':new['FunctionName'],'codeSha256':new['CodeSha256'],'revisionId':new['RevisionId'],'changedEnvironmentKeys':['DELIVERY_QUOTES_ENABLED'],'quoteDeletionHookEnabled':True,'otherConfigurationPreserved':True});state['workerInvokedByRelease']=False;state['verifiedAtUtc']=datetime.datetime.now(datetime.timezone.utc).isoformat();save();print(json.dumps({'quoteCleanupHookEnabled':True,'workerInvoked':False,'financialActivation':False}))
if __name__=='__main__':main()
